function validate(input) {
  const [fn, args, t, cancelTimeMs] = input;
  const described = fn === 'product' || (fn !== null && typeof fn === 'object' && !Array.isArray(fn) && Object.keys(fn).length === 1
    && ((Number.isInteger(fn.times) && Math.abs(fn.times) <= 100) || (Number.isInteger(fn.power) && fn.power >= 0 && fn.power <= 5)));
  if (!described) return 'fn must be "product", { "times": k } with k from -100 to 100, or { "power": k } with k from 0 to 5.';
  if (!Array.isArray(args) || args.length < 1 || args.length > 10 || !args.every(x => Number.isInteger(x) && x >= -20 && x <= 20)) return 'args must hold 1 to 10 integers from -20 to 20.';
  if (!Number.isInteger(t) || t < 20 || t > 1000) return 't must be an integer from 20 to 1000.';
  if (!Number.isInteger(cancelTimeMs) || cancelTimeMs < 10 || cancelTimeMs > 1000) return 'cancelTimeMs must be an integer from 10 to 1000.';
  if (t === cancelTimeMs) return 'Pick a cancelTimeMs different from t, so the result does not depend on a tie.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [spec, args, t, cancelTimeMs] = input;
  const compute = values => {
    if (spec === 'product') return values.reduce((product, x) => product * x, 1);
    if (Object.hasOwn(spec, 'times')) return values[0] * spec.times;
    return values[0] ** spec.power;
  };
  const start = Date.now(), runs = [];
  const fn = (...values) => {
    const returned = compute(values);
    runs.push({ time: Date.now() - start, returned });
    kit.trace(`fn(${values.map(value => JSON.stringify(value)).join(', ')}) runs and returns ${returned}`);
    return returned;
  };
  kit.trace(`cancellable(fn, [${args.join(', ')}], ${t}) is called`);
  const cancelFn = solve(fn, args, t);
  if (typeof cancelFn !== 'function') throw new Error('cancellable must return a function.');
  setTimeout(() => {
    kit.trace('cancelFn() is called');
    cancelFn();
  }, cancelTimeMs);
  // Every run is over once both the delay and the cancellation have passed.
  return new Promise(resolve => setTimeout(() => resolve(runs), Math.max(t, cancelTimeMs) + 15));
}

