function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const kind = Math.floor(rand() * 3);
  const fn = kind === 0 ? { times: int(-10, 10) } : kind === 1 ? { power: int(0, 5) } : 'product';
  const args = Array.from({ length: int(1, size === 'small' ? 4 : 10) }, () => int(-20, 20));
  const t = int(20, size === 'small' ? 200 : 1000);
  let cancelTimeMs = int(10, size === 'small' ? 200 : 1000);
  if (cancelTimeMs === t) cancelTimeMs = t > 500 ? t - 1 : t + 1;
  return [fn, args, t, cancelTimeMs];
}
